Input: {"question": "When was Christ Lutheran Church founded?", "source_segments": {"D1S1": {"document_number": 1, "doc_id": "ramdocs-0358-c07b1d2042d8:d00", "start": 0, "end": 159, "text": "Christ Evangelical Lutheran Church Christ Evangelical Lutheran Church is a church located southwest of the Walker's Point neighborhood of Milwaukee, Wisconsin."}, "D1S2": {"document_number": 1, "doc_id": "ramdocs-0358-c07b1d2042d8:d00", "start": 160, "end": 217, "text": "It is listed on the National Register of Historic Places."}, "D1S3": {"document_number": 1, "doc_id": "ramdocs-0358-c07b1d2042d8:d00", "start": 218, "end": 331, "text": "Christ Evangelical Lutheran Church was founded in 1884 by thirteen families who were peacefully released from St."}, "D1S4": {"document_number": 1, "doc_id": "ramdocs-0358-c07b1d2042d8:d00", "start": 332, "end": 368, "text": "Peter's Evangelical Lutheran Church."}, "D1S5": {"document_number": 1, "doc_id": "ramdocs-0358-c07b1d2042d8:d00", "start": 369, "end": 426, "text": "Services were initially conducted in a private residence."}, "D1S6": {"document_number": 1, "doc_id": "ramdocs-0358-c07b1d2042d8:d00", "start": 427, "end": 530, "text": "Later in 1884, Christ Evangelical Lutheran Church erected a wooden building east of the present church."}, "D1S7": {"document_number": 1, "doc_id": "ramdocs-0358-c07b1d2042d8:d00", "start": 531, "end": 624, "text": "This structure housed both church and school until 1901 and the school until the early 1970s."}, "D1S8": {"document_number": 1, "doc_id": "ramdocs-0358-c07b1d2042d8:d00", "start": 625, "end": 679, "text": "The church was designed by architect Frederick Velguth"}, "D2S1": {"document_number": 2, "doc_id": "ramdocs-0358-c07b1d2042d8:d01", "start": 0, "end": 124, "text": "Christ Evangelical Lutheran Church is a church located southwest of the Walker's Point neighborhood of Milwaukee, Wisconsin."}, "D2S2": {"document_number": 2, "doc_id": "ramdocs-0358-c07b1d2042d8:d01", "start": 125, "end": 182, "text": "It is listed on the National Register of Historic Places."}, "D2S3": {"document_number": 2, "doc_id": "ramdocs-0358-c07b1d2042d8:d01", "start": 183, "end": 296, "text": "Christ Evangelical Lutheran Church was founded in 1920 by thirteen families who were peacefully released from St."}, "D2S4": {"document_number": 2, "doc_id": "ramdocs-0358-c07b1d2042d8:d01", "start": 297, "end": 333, "text": "Peter's Evangelical Lutheran Church."}, "D2S5": {"document_number": 2, "doc_id": "ramdocs-0358-c07b1d2042d8:d01", "start": 334, "end": 391, "text": "Services were initially conducted in a private residence."}, "D2S6": {"document_number": 2, "doc_id": "ramdocs-0358-c07b1d2042d8:d01", "start": 392, "end": 495, "text": "Later in 1920, Christ Evangelical Lutheran Church erected a wooden building east of the present church."}, "D2S7": {"document_number": 2, "doc_id": "ramdocs-0358-c07b1d2042d8:d01", "start": 496, "end": 589, "text": "This structure housed both church and school until 1901 and the school until the early 1970s."}, "D2S8": {"document_number": 2, "doc_id": "ramdocs-0358-c07b1d2042d8:d01", "start": 590, "end": 645, "text": "The church was designed by architect Frederick Velguth."}, "D3S1": {"document_number": 3, "doc_id": "ramdocs-0358-c07b1d2042d8:d02", "start": 0, "end": 166, "text": "Christ Lutheran Church, Narsapur Christ Lutheran Church is a congregation in the Andhra Evangelical Lutheran Church and is a member church of the West Godavari synod."}, "D3S2": {"document_number": 3, "doc_id": "ramdocs-0358-c07b1d2042d8:d02", "start": 167, "end": 302, "text": "It is a major A class parish and is a mother church to several smaller and younger congregations in and around Narsapur, West Godavari."}, "D3S3": {"document_number": 3, "doc_id": "ramdocs-0358-c07b1d2042d8:d02", "start": 303, "end": 331, "text": "The current pastors are Rev."}, "D3S4": {"document_number": 3, "doc_id": "ramdocs-0358-c07b1d2042d8:d02", "start": 332, "end": 384, "text": "V.Rajendra Sundar and Assist.pastor Rev.P.P.S.kiran."}, "D3S5": {"document_number": 3, "doc_id": "ramdocs-0358-c07b1d2042d8:d02", "start": 385, "end": 439, "text": "The church follows the Lutheran liturgical traditions."}, "D3S6": {"document_number": 3, "doc_id": "ramdocs-0358-c07b1d2042d8:d02", "start": 440, "end": 604, "text": "The corner stone was established in 1923 by Fr.Barger and Fr.Heyer and the Church was started in 1929 and is therefore more recent than other churches in the synod."}, "D3S7": {"document_number": 3, "doc_id": "ramdocs-0358-c07b1d2042d8:d02", "start": 605, "end": 636, "text": "Several pastors have ministered"}, "D4S1": {"document_number": 4, "doc_id": "ramdocs-0358-c07b1d2042d8:d03", "start": 0, "end": 240, "text": "Christ Lutheran Church (Ellenville, New York) Christ Lutheran Church and Parsonage, originally the German Evangelical Lutheran Church of Ellenville, is a historic Lutheran church and parsonage located at Ellenville, Ulster County, New York."}, "D4S2": {"document_number": 4, "doc_id": "ramdocs-0358-c07b1d2042d8:d03", "start": 241, "end": 297, "text": "The church was built in 1862 in the Greek Revival style."}, "D4S3": {"document_number": 4, "doc_id": "ramdocs-0358-c07b1d2042d8:d03", "start": 298, "end": 435, "text": "It was moved, enlarged, reoriented, and completely remodeled in 1903–1904 in the Gothic Revival style when moved to its present location."}, "D4S4": {"document_number": 4, "doc_id": "ramdocs-0358-c07b1d2042d8:d03", "start": 436, "end": 582, "text": "It is a roughly L-shaped building, with a T-shaped main block consisting of a -story, gable-roofed front block and -story gable-roofed rear block."}, "D4S5": {"document_number": 4, "doc_id": "ramdocs-0358-c07b1d2042d8:d03", "start": 583, "end": 620, "text": "Appended to it is a 1-story addition."}, "D4S6": {"document_number": 4, "doc_id": "ramdocs-0358-c07b1d2042d8:d03", "start": 621, "end": 653, "text": "It features a two-tiered, square"}, "D5S1": {"document_number": 5, "doc_id": "ramdocs-0358-c07b